describe('Cookie Consent Banner', () => {
  beforeEach(() => {
    cy.visit('/')
    cy.clearCookies()
    cy.reload()
  })

  it('should display cookie consent banner on page load', () => {
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible')
    cy.get('[data-testid="cookie-consent-banner"]').should('contain', 'We use cookies')
    cy.get('[data-testid="accept-cookies-btn"]').should('be.visible')
    cy.get('[data-testid="reject-cookies-btn"]').should('be.visible')
  })

  it('should hide banner after accepting cookies', () => {
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible')
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.getCookie('cookie_consent').should('exist')
    cy.getCookie('cookie_consent').should('have.property', 'value', 'accepted')
  })

  it('should persist cookie consent decision across page reloads', () => {
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.reload()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.getCookie('cookie_consent').should('have.property', 'value', 'accepted')
  })

  it('should hide banner after rejecting cookies', () => {
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible')
    cy.get('[data-testid="reject-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.getCookie('cookie_consent').should('have.property', 'value', 'rejected')
  })

  it('should handle rapid accept button clicks without errors', () => {
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.getCookie('cookie_consent').should('exist')
  })

  it('should display banner with proper accessibility attributes', () => {
    cy.get('[data-testid="cookie-consent-banner"]')
      .should('have.attr', 'role', 'dialog')
    cy.get('[data-testid="accept-cookies-btn"]')
      .should('have.attr', 'aria-label')
    cy.get('[data-testid="reject-cookies-btn"]')
      .should('have.attr', 'aria-label')
  })

  it('should allow keyboard navigation and acceptance', () => {
    cy.get('[data-testid="accept-cookies-btn"]').focus()
    cy.get('[data-testid="accept-cookies-btn"]').should('have.focus')
    cy.get('[data-testid="accept-cookies-btn"]').type('{enter}')
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
  })

  it('should handle banner dismissal with animation', () => {
    cy.get('[data-testid="cookie-consent-banner"]')
      .should('have.css', 'opacity', '1')
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]')
      .should('have.css', 'opacity', '0')
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
  })

  it('should not show banner when cookie consent is already set', () => {
    cy.setCookie('cookie_consent', 'accepted')
    cy.visit('/')
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
  })

  it('should handle edge case where banner element is missing gracefully', () => {
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible')
    cy.get('[data-testid="accept-cookies-btn"]').click()
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist')
    cy.get('[data-testid="cookie-consent-banner"]').should('have.length', 0)
  })
})
